function.arguments:
{"script": "mkdir test_directory
n=$((RANDOM % 5 + 3))
for i in {1..$n}; do mkdir test_directory/subdir$i; done
for i in {1..$n}; do m=$((RANDOM % 7 + 4))
for j in {1..$m}; do echo "$(tr -cd '[:alnum:]' < /dev/urandom | fold -w 10 | head -n 1)" > test_directory/subdir$i/file$j; done; done
du -s --block-size=1 test_directory/* | awk '{sum += $1} END {print sum}'"}

{"script": "files=$(find test_directory -type f | wc -l);
directories=$(find test_directory -type d | wc -l);
directories=$((directories - 1));
size=$(du -sk test_directory | awk '{print $1}');
total=$((files + directories + size));
echo $total"}

